import { z } from 'zod';
import { WORKER_SKILLS, WORKER_TYPES, type WorkerSkill, type WorkerType } from '../enums';
import {
  dateOnlySchema,
  enumField,
  isOnOrAfter,
  optionalDate,
  optionalMoney,
  optionalText,
  queryBoolean,
  requiredText,
} from './common';
import { paginationQuerySchema } from './pagination';

/** Worker code: W-NNNN (generated by the API). */
export const WORKER_CODE_REGEX = /^W-\d{4,}$/;

/** Sri Lankan NIC: old (9 digits + V/X) or new (12 digits). */
export const NIC_OLD_REGEX = /^\d{9}[VvXx]$/;
export const NIC_NEW_REGEX = /^\d{12}$/;

export function isValidNic(value: string): boolean {
  return NIC_OLD_REGEX.test(value) || NIC_NEW_REGEX.test(value);
}

/** Normalises a NIC for storage: no spaces, upper-case V/X. */
export function normalizeNic(value: string): string {
  return value.replace(/\s+/g, '').toUpperCase();
}

const nicField = z
  .union([z.literal(''), z.string()])
  .nullable()
  .optional()
  .transform((v) => (v === undefined ? undefined : v ? normalizeNic(v) : null))
  .refine((v) => v === undefined || v === null || v === '' || isValidNic(v), {
    message: 'INVALID_NIC',
  })
  .transform((v) => (v === '' ? null : v));

const workerFields = z.object({
  fullName: requiredText(200),
  nameSinhala: optionalText(200),
  nic: nicField,
  phone: optionalText(50),
  address: optionalText(500),
  dateOfBirth: optionalDate,
  skill: enumField(WORKER_SKILLS),
  type: enumField(WORKER_TYPES),
  joinedDate: dateOnlySchema,
  leftDate: optionalDate,
  active: z.boolean().optional(),
  epfNo: optionalText(50),
  bankName: optionalText(100),
  bankAccountNo: optionalText(50),
  emergencyContact: optionalText(200),
  notes: optionalText(2000),
});

const rateFields = {
  dailyRate: optionalMoney,
  monthlySalary: optionalMoney,
  otHourlyRate: optionalMoney,
};

type RateCheck = {
  type?: WorkerType;
  dailyRate?: string | null;
  monthlySalary?: string | null;
};

/** DAILY workers need a daily rate, PERMANENT workers a monthly salary. */
export function rateIssues(
  v: RateCheck,
): { path: 'dailyRate' | 'monthlySalary'; message: string }[] {
  if (v.type === 'DAILY' && !v.dailyRate) return [{ path: 'dailyRate', message: 'REQUIRED' }];
  if (v.type === 'PERMANENT' && !v.monthlySalary) {
    return [{ path: 'monthlySalary', message: 'REQUIRED' }];
  }
  return [];
}

/** POST /workers — the starting pay becomes the first rate (effective from the joined date). */
export const workerCreateSchema = workerFields.extend(rateFields).superRefine((v, ctx) => {
  if (!isOnOrAfter(v.joinedDate, v.leftDate)) {
    ctx.addIssue({ code: 'custom', path: ['leftDate'], message: 'END_BEFORE_START' });
  }
  for (const issue of rateIssues(v)) {
    ctx.addIssue({ code: 'custom', path: [issue.path], message: issue.message });
  }
});
export type WorkerCreateInput = z.input<typeof workerCreateSchema>;
export type WorkerCreate = z.output<typeof workerCreateSchema>;

export const workerUpdateSchema = workerFields.partial().superRefine((v, ctx) => {
  if (!isOnOrAfter(v.joinedDate, v.leftDate)) {
    ctx.addIssue({ code: 'custom', path: ['leftDate'], message: 'END_BEFORE_START' });
  }
});
export type WorkerUpdate = z.output<typeof workerUpdateSchema>;

export const workerListQuerySchema = paginationQuerySchema.extend({
  type: z.enum(WORKER_TYPES).optional(),
  skill: z.enum(WORKER_SKILLS).optional(),
  active: queryBoolean,
});
export type WorkerListQuery = z.infer<typeof workerListQuerySchema>;

/** POST /workers/:id/rates — a new pay rate from a date (one per date). */
export const workerRateCreateSchema = z.object({ effectiveFrom: dateOnlySchema, ...rateFields });
export type WorkerRateCreateInput = z.input<typeof workerRateCreateSchema>;
export type WorkerRateCreate = z.output<typeof workerRateCreateSchema>;

export interface WorkerRateDto {
  id: string;
  workerId: string;
  effectiveFrom: string;
  dailyRate: string | null;
  monthlySalary: string | null;
  otHourlyRate: string | null;
  createdAt: string;
}

export interface WorkerDto {
  id: string;
  code: string;
  fullName: string;
  nameSinhala: string | null;
  nic: string | null;
  phone: string | null;
  address: string | null;
  dateOfBirth: string | null;
  skill: WorkerSkill;
  type: WorkerType;
  joinedDate: string;
  leftDate: string | null;
  active: boolean;
  epfNo: string | null;
  bankName: string | null;
  bankAccountNo: string | null;
  emergencyContact: string | null;
  photoDocId: string | null;
  notes: string | null;
  createdAt: string;
  updatedAt: string;
  /** The rate in force today (Asia/Colombo), or null. */
  currentRate: WorkerRateDto | null;
}
